         <div className="w-16 h-16 md:w-20 md:h-20 dark:bg-blue-500/20 bg-blue-500/10 text-blue-500 rounded-[24px] md:rounded-[32px] flex items-center justify-center shadow-inner border border-blue-500/10 shrink-0">
           <BookOpen size={32} className="md:w-10 md:h-10" />
